identity:
"""Persistent issuer identity and attributed observations. All operations are offline.

Aliases use inclusive valid_from and exclusive valid_to. CIK identifies an
issuer, not a security: price series retain their source ticker and never merge
concurrent share classes merely because their CIK matches.
"""
import hashlib
import json
import re
import uuid
from datetime import date

import pandas as pd

from . import storage

SCHEMA = """
CREATE TABLE IF NOT EXISTS entities (
    entity_id TEXT PRIMARY KEY, cik TEXT UNIQUE, name TEXT, created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS entity_aliases (
    entity_id TEXT NOT NULL REFERENCES entities(entity_id), symbol TEXT NOT NULL,
    valid_from TEXT NOT NULL, valid_to TEXT, source TEXT NOT NULL,
    confidence REAL NOT NULL CHECK(confidence >= 0 AND confidence <= 1),
    PRIMARY KEY(entity_id, symbol, valid_from, source),
    CHECK(valid_to IS NULL OR valid_to > valid_from)
);
CREATE INDEX IF NOT EXISTS idx_entity_alias_symbol ON entity_aliases(symbol, valid_from, valid_to);
CREATE TABLE IF NOT EXISTS entity_observations (
    entity_id TEXT NOT NULL REFERENCES entities(entity_id), dataset TEXT NOT NULL,
    symbol TEXT NOT NULL, record_key TEXT NOT NULL, payload_json TEXT NOT NULL,
    source TEXT NOT NULL,
    PRIMARY KEY(entity_id, dataset, symbol, record_key)
);
CREATE INDEX IF NOT EXISTS idx_entity_observations_dataset_symbol
    ON entity_observations(dataset, symbol);
CREATE TABLE IF NOT EXISTS entity_candidates (
    symbol TEXT NOT NULL, entity_id TEXT NOT NULL REFERENCES entities(entity_id),
    name TEXT, source TEXT NOT NULL, reason TEXT NOT NULL,
    PRIMARY KEY(symbol, entity_id, source)
);
"""

MIN_CONFIDENCE = 0.9
DATA_KEYS = {
    "prices": ("date",), "splits": ("date",), "fundamentals": ("fetched_at",),
    "edgar_facts": ("tag", "unit", "start_date", "end_date", "accn"),
    "sector": ("effective_date",), "filing_identity": ("accession",),
}


def ensure_schema(conn):
    # execute, rather than executescript: do not commit the caller's transaction.
    for statement in SCHEMA.split(";"):
        if statement.strip():
            conn.execute(statement)


def normalize_symbol(symbol: str) -> str:
    return symbol.strip().upper().replace(".", "-")


def normalize_cik(cik) -> str:
    value = str(cik).strip()
    if not value.isdigit() or len(value) > 10 or int(value) == 0:
        raise ValueError("CIK must contain 1-10 digits and be nonzero")
    return value.zfill(10)


def ensure_entity(cik=None, name: str | None = None, *, entity_id: str | None = None) -> str:
    cik = normalize_cik(cik) if cik is not None else None
    name = None if pd.isna(name) else name
    derived = f"cik:{cik}" if cik else entity_id or f"local:{uuid.uuid4()}"
    if cik and entity_id and entity_id != derived:
        raise ValueError("entity_id conflicts with CIK")
    with storage.get_connection() as conn:
        ensure_schema(conn)
        existing = conn.execute("SELECT cik FROM entities WHERE entity_id=?", (derived,)).fetchone()
        if existing and existing[0] != cik:
            raise ValueError("An entity's CIK cannot be reassigned")
        conn.execute("INSERT INTO entities VALUES (?,?,?,?) ON CONFLICT(entity_id) DO UPDATE "
                     "SET name=COALESCE(excluded.name,entities.name)",
                     (derived, cik, name, date.today().isoformat()))
        conn.commit()
    return derived


def add_alias(entity_id: str, symbol: str, valid_from: str, valid_to: str | None = None,
              *, source: str, confidence: float = 1.0):
    """Record dated evidence. Conflicting evidence is retained as ambiguous."""
    start = date.fromisoformat(valid_from).isoformat()
    end = date.fromisoformat(valid_to).isoformat() if valid_to else None
    if not source.strip() or not 0 <= confidence <= 1 or (end and end <= start):
        raise ValueError("Invalid alias evidence, confidence or validity interval")
    symbol = normalize_symbol(symbol)
    if not symbol:
        raise ValueError("Empty symbol")
    with storage.get_connection() as conn:
        ensure_schema(conn)
        if not conn.execute("SELECT 1 FROM entities WHERE entity_id=?", (entity_id,)).fetchone():
            raise ValueError("Unknown entity")
        conn.execute("INSERT INTO entity_aliases VALUES (?,?,?,?,?,?) "
                     "ON CONFLICT(entity_id,symbol,valid_from,source) DO UPDATE SET "
                     "valid_to=excluded.valid_to, confidence=excluded.confidence",
                     (entity_id, symbol, start, end, source, confidence))
        conn.commit()


def resolve(symbol: str, as_of: str) -> dict:
    date.fromisoformat(as_of)
    with storage.get_connection() as conn:
        ensure_schema(conn)
        rows = conn.execute(
            "SELECT a.entity_id,e.cik,a.source,a.confidence FROM entity_aliases a "
            "JOIN entities e USING(entity_id) WHERE symbol=? AND valid_from<=? "
            "AND (valid_to IS NULL OR valid_to>?)",
            (normalize_symbol(symbol), as_of, as_of),
        ).fetchall()
    if not rows:
        from . import historical_pit
        if historical_pit.covers(as_of):
            # Sin alias operativo: en 2010-2015 vale la identidad SEC acreditada.
            return historical_pit.resolve(symbol, as_of)
    candidates = sorted({r[0] for r in rows})
    # Even a low-confidence contradictory claim must not silently win/lose.
    status = "ambiguous" if len(candidates) > 1 else "unresolved"
    chosen = max(rows, key=lambda r: r[3]) if rows else None
    if len(candidates) == 1 and chosen and chosen[3] >= MIN_CONFIDENCE:
        status = "resolved"
    return {"entity_id": chosen[0] if status == "resolved" and chosen else None,
            "cik": chosen[1] if status == "resolved" and chosen else None,
            "status": status, "candidates": candidates,
            "source": chosen[2] if chosen else None,
            "confidence": chosen[3] if chosen else None}


def has_aliases(symbol: str) -> bool:
    with storage.get_connection() as conn:
        ensure_schema(conn)
        return bool(conn.execute("SELECT 1 FROM entity_aliases WHERE symbol=? LIMIT 1",
                                 (normalize_symbol(symbol),)).fetchone())


def put_observations(conn, entity_id: str, dataset: str, symbol: str, rows: list[dict], source: str):
    """Atomic dual-write used by ingestion; attribution must be explicit."""
    ensure_schema(conn)
    if dataset not in DATA_KEYS or not source:
        raise ValueError("Unknown dataset or missing attribution source")
    if not conn.execute("SELECT 1 FROM entities WHERE entity_id=?", (entity_id,)).fetchone():
        raise ValueError("Unknown entity")
    records = []
    for row in rows:
        row = _json_value(row)
        key = json.dumps([row.get(k, "") for k in DATA_KEYS[dataset]], separators=(",", ":"))
        payload = json.dumps(row, sort_keys=True, default=str, allow_nan=False)
        records.append((entity_id, dataset, normalize_symbol(symbol), key, payload, source))
    if dataset == "edgar_facts":
        # A filing fact is issuer-wide. A refresh under a new alias supersedes
        # the same fact downloaded under the former ticker, not an arbitrary
        # alphabetical duplicate selected at read time.
        conn.executemany("DELETE FROM entity_observations WHERE entity_id=? AND dataset=? AND record_key=?",
                         [(entity_id, dataset, r[3]) for r in records])
    conn.executemany("INSERT OR REPLACE INTO entity_observations VALUES (?,?,?,?,?,?)", records)


def _json_value(value):
    if isinstance(value, dict):
        return {key: _json_value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_value(item) for item in value]
    if pd.isna(value):
        return None
    return value.item() if hasattr(value, "item") else value


def observations(entity_id: str, dataset: str) -> pd.DataFrame:
    with storage.get_connection() as conn:
        ensure_schema(conn)
        rows = conn.execute("SELECT symbol,payload_json FROM entity_observations "
                            "WHERE entity_id=? AND dataset=? ORDER BY symbol,record_key",
                            (entity_id, dataset)).fetchall()
    return pd.DataFrame([{**json.loads(payload), "source_symbol": symbol} for symbol, payload in rows])


def price_history(symbol: str, as_of: str, *, entity_id: str | None = None) -> pd.DataFrame:
    """Prices attributed to the resolved issuer; never reads the legacy cache.

    Keep a source series intact (split adjustments can differ between downloads).
    Prefer the requested ticker, otherwise allow a single non-concurrent alias.
    Multiple share classes or competing series fail closed.
    """
    resolved = resolve(symbol, as_of)
    owner = entity_id or resolved["entity_id"]
    if not owner or resolved["status"] == "ambiguous" or (resolved["entity_id"] and resolved["entity_id"] != owner):
        return pd.DataFrame()
    from . import historical_pit
    if historical_pit.covers(as_of):
        return historical_pit.ranking_series(owner, as_of)
    frame = observations(owner, "prices")
    if frame.empty:
        return frame
    requested = normalize_symbol(symbol)
    sources = set(frame["source_symbol"])
    if requested in sources:
        frame = frame[frame["source_symbol"] == requested]
    elif len(sources) == 1:
        other = next(iter(sources))
        with storage.get_connection() as conn:
            ensure_schema(conn)
            overlap = conn.execute(
                "SELECT 1 FROM entity_aliases a JOIN entity_aliases b ON a.entity_id=b.entity_id "
                "WHERE a.entity_id=? AND a.symbol=? AND b.symbol=? "
                "AND a.valid_from<COALESCE(b.valid_to,'9999-12-31') "
                "AND b.valid_from<COALESCE(a.valid_to,'9999-12-31') LIMIT 1",
                (owner, requested, other)).fetchone()
        if overlap:
            return pd.DataFrame()
    else:
        return pd.DataFrame()
    # A full history returned for a current ticker can predate that ticker.
    # Its entity attribution is explicit, but observations outside any confirmed
    # alias interval for that issuer must still not extend its known lifetime.
    with storage.get_connection() as conn:
        aliases = conn.execute("SELECT valid_from,valid_to FROM entity_aliases WHERE entity_id=? "
                               "AND confidence>=?", (owner, MIN_CONFIDENCE)).fetchall()
        conflicts = conn.execute(
            "SELECT valid_from,valid_to FROM entity_aliases WHERE symbol=? AND entity_id<>?",
            (requested, owner)).fetchall()
    mask = pd.Series(False, index=frame.index)
    for start, end in aliases:
        mask |= (frame["date"] >= start) & (frame["date"] < (end or "9999-12-31"))
    for start, end in conflicts:
        mask &= ~((frame["date"] >= start) & (frame["date"] < (end or "9999-12-31")))
    frame = frame[mask].copy()
    source_symbol = str(frame["source_symbol"].iloc[0]) if not frame.empty else requested
    frame["date"] = pd.to_datetime(frame["date"])
    result = frame.drop(columns=["source_symbol"]).set_index("date").sort_index()
    result.attrs["source_symbol"] = source_symbol
    return result


def diagnostics(symbols: list[str], as_of: str) -> pd.DataFrame:
    return pd.DataFrame([{"symbol": s, **resolve(s, as_of)} for s in sorted(set(symbols))])


def price_download_symbol(symbol: str, as_of: str, *, today: str | None = None) -> str | None:
    """A live ticker for this historical issuer, only if unambiguous.

    Delisted issuers without a verified successor require an archived series.
    A different company reusing the old symbol is never a download fallback.
    """
    today = today or date.today().isoformat()
    owner = resolve(symbol, as_of)["entity_id"]
    if not owner:
        return None
    if resolve(symbol, today)["entity_id"] == owner:
        return symbol
    with storage.get_connection() as conn:
        aliases = conn.execute("SELECT DISTINCT symbol FROM entity_aliases WHERE entity_id=? "
                               "AND valid_from<=? AND (valid_to IS NULL OR valid_to>?) AND confidence>=?",
                               (owner, today, today, MIN_CONFIDENCE)).fetchall()
    candidates = [r[0] for r in aliases if resolve(r[0], today)["entity_id"] == owner]
    if len(candidates) != 1:
        return None
    with storage.get_connection() as conn:
        overlap = conn.execute(
            "SELECT 1 FROM entity_aliases a JOIN entity_aliases b USING(entity_id) "
            "WHERE a.entity_id=? AND a.symbol=? AND b.symbol=? "
            "AND a.valid_from<COALESCE(b.valid_to,'9999-12-31') "
            "AND b.valid_from<COALESCE(a.valid_to,'9999-12-31') LIMIT 1",
            (owner, normalize_symbol(symbol), candidates[0])).fetchone()
    return None if overlap else candidates[0]


def backtest_prices(symbols: list[str], as_of: str, owners: dict | None = None) -> dict:
    """Entity data for registered issuers; legacy adapter for unmigrated callers.

    Strict ranking excludes unresolved issuers before selection. Other legacy
    callers retain their API; they never bypass a registered/conflicting alias.
    SPY remains the explicitly configured benchmark security, not an issuer.
    """
    from . import config, historical_pit
    historical = historical_pit.covers(as_of)
    result = {}
    for symbol in symbols:
        owner = owners.get(symbol) if owners else None
        if symbol != config.BENCHMARK_SYMBOL:
            if historical and not owner:
                owner = resolve(symbol, as_of)["entity_id"]
            if historical_pit.has_series(owner, as_of):
                # Serie acreditada con su periodo de tenencia verificado.
                result[symbol] = historical_pit.holding_series(owner, as_of)
                continue
            if historical:
                # 2010-2015 nunca recurre a la caché por ticker.
                result[symbol] = pd.DataFrame()
                continue
        if symbol != config.BENCHMARK_SYMBOL and (owner or has_aliases(symbol)):
            result[symbol] = price_history(symbol, as_of, entity_id=owner)
        else:
            result[symbol] = storage.get_prices(symbol)
    return result


def last_filings(symbols: list[str], as_of: str) -> dict:
    from . import edgar
    result = {}
    legacy = []
    for symbol in symbols:
        owner = resolve(symbol, as_of)["entity_id"]
        if owner:
            frame = observations(owner, "edgar_facts")
            if not frame.empty:
                dates = frame.loc[frame["filed_date"].notna() & (frame["filed_date"] <= as_of), "filed_date"]
                if not dates.empty:
                    result[symbol] = dates.max()
        elif not has_aliases(symbol):
            legacy.append(symbol)
    result.update(edgar.get_last_filed_dates(legacy, as_of=as_of))
    return result


def _name_key(name: str) -> str:
    return re.sub(r"[^a-z0-9]", "", name.casefold())


def import_submissions_candidates(symbol: str, historical_name: str, submissions: dict, *, source: str) -> bool:
    """Offline formerNames/name fallback. A match is a candidate, never an alias.

    Dates on formerNames describe names, not ticker trading validity.
    """
    names = [submissions.get("name", ""), *[r.get("name", "") for r in submissions.get("formerNames", [])]]
    if not historical_name or _name_key(historical_name) not in {_name_key(n) for n in names if n}:
        return False
    entity = ensure_entity(submissions["cik"], submissions.get("name"))
    with storage.get_connection() as conn:
        conn.execute("INSERT OR REPLACE INTO entity_candidates VALUES (?,?,?,?,?)",
                     (normalize_symbol(symbol), entity, historical_name, source,
                      "Exact normalized name/formerNames match; requires dated ticker evidence"))
        conn.commit()
    return True


def import_filing_identity(symbol: str, cik: str, filing_date: str, *, source: str,
                           name: str | None = None):
    """A filing cover proves a ticker/CIK on its filing date, not an interval."""
    from datetime import timedelta

    entity = ensure_entity(cik, name)
    end = (date.fromisoformat(filing_date) + timedelta(days=1)).isoformat()
    add_alias(entity, symbol, filing_date, end, source=source)
    return entity


def attributed_fingerprint() -> str:
    with storage.get_connection() as conn:
        ensure_schema(conn)
        payload = {table: conn.execute(f"SELECT * FROM {table} ORDER BY 1,2,3").fetchall()
                   for table in ("entities", "entity_aliases", "entity_observations", "entity_candidates")}
    return hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()

historical_pit:
"""Adaptador point-in-time acreditado para Ranking histórico y Backtest V1/V2 (#32, #34).

El motor existente (``universe`` → ``screener_asof`` → ``identity``) se usa tal
cual; este módulo solo le da, para fechas cubiertas por la capa histórica
acreditada en #26-#28, lo que antes obtenía de la caché por ticker:

- universo: composición de referencia fja05680 con la corrección WLP/ANTM
  (la misma sobre la que se acreditaron identidad y precios);
- identidad: intervalos SEC acreditados (#27/#29/#28), nunca alias actuales;
- precios: solo intervalos de ``historical_price_provenance`` (una fuente por
  lectura, sin concatenar ni rellenar), que incluyen el periodo de tenencia
  verificado hasta el siguiente rebalanceo;
- salida de una posición: evento terminal confirmado (contraprestación en
  efectivo) o, si no lo hay, el último precio marcado explícitamente como no
  estricto. Nunca se oculta.

Por defecto solo está activo 2010-2015 (``[HISTORICAL_START, HISTORICAL_END)``);
fuera de él no cambia nada. La capa 2016-2025 (#34) se activa explícitamente con
``accredited_periods("2010-2015", "2016-2025")`` para compararla con el camino
operativo (#35); sin activarla, los rankings 2016+ son los de siempre.
"""

import json
from collections.abc import Iterator
from contextlib import contextmanager
from datetime import date, timedelta

import pandas as pd

from gabi.domain.market.sec_identity import accredited_resolution

from . import historical_archive, historical_membership, historical_period, identity, storage
from .historical_price_policy import ADJUSTED, YAHOO_SOURCE
from .historical_price_policy import SCHEMA as PROVENANCE_SCHEMA

HISTORICAL_START = historical_period.P2010.start
HISTORICAL_END = historical_period.P2010.end_exclusive
TRAILING_DAYS = 365  # ~253 sesiones: la ventana que exigen momentum y riesgo
# Fechas auditadas por las auditorías trimestrales de precios (#28, #34). Cada
# periodo solo tiene ventanas acreditadas si se ejecutó su auditoría.
QUARTER_ENDS = {quarter for period in historical_period.PERIODS.values() for quarter in period.quarters}
_active: tuple[historical_period.Period, ...] = (historical_period.P2010,)


@contextmanager
def accredited_periods(*keys: str) -> Iterator[None]:
    """Activa temporalmente los periodos acreditados indicados (p. ej. 2016-2025)."""
    global _active
    previous = _active
    _active = tuple(historical_period.get(key) for key in keys)
    try:
        yield
    finally:
        _active = previous


def active_periods() -> tuple[str, ...]:
    return tuple(period.key for period in _active)


def period_for(as_of: str) -> historical_period.Period | None:
    day = date.fromisoformat(as_of[:10]).isoformat()
    return next((period for period in _active if period.covers(day)), None)


def covers(as_of: str) -> bool:
    return period_for(as_of) is not None


def _period(as_of: str) -> historical_period.Period:
    period = period_for(as_of)
    if period is None:
        raise ValueError(f"{as_of[:10]} is outside the active accredited periods {active_periods()}")
    return period


def _constituents(as_of: str) -> dict:
    period = _period(as_of)
    return historical_membership.constituents_as_of(
        as_of, source_id=period.membership_source, compare_reference=False,
        identity_source=period.identity_source)


def universe(as_of: str) -> dict:
    """Mismo contrato que ``universe.get_sp500_constituents_asof``."""
    data = _constituents(as_of)
    members = data["members"]
    accredited = sum(1 for row in members if row["identity_status"] == "resolved")
    return {"symbols": data["symbols"], "source_date": data["source_date"], "is_exact": True,
            "label_corrections": data["label_corrections"],
            "source_id": data["source_id"], "quality": data["quality"],
            "identity_accredited": accredited,
            "note": (f"Composición histórica de referencia ({data['source_id']}) del {data['source_date']}, "
                     f"aplicable a {as_of}; identidad acreditada {accredited}/{len(members)}. "
                     f"Capa {_period(as_of).key}: solo precios y entidades acreditados por SEC.")}


def resolve(symbol: str, as_of: str) -> dict:
    """Mismo contrato que ``identity.resolve`` con la identidad histórica acreditada."""
    found = historical_membership._identities({identity.normalize_symbol(symbol)}, as_of,
                                              interval_source=_period(as_of).identity_source)
    row = found[identity.normalize_symbol(symbol)]
    return accredited_resolution(row)


def _intervals(entity_id: str) -> list[tuple]:
    """Accredited intervals of the active periods' audits (plus intervals
    recorded outside an audit, without a producer)."""
    producers = {period.price_producer for period in _active}
    with storage.get_connection() as conn:
        conn.executescript(historical_archive.SCHEMA + PROVENANCE_SCHEMA)
        rows = conn.execute(
            "SELECT source_id,symbol,valid_from,valid_to,status,evidence_json FROM historical_price_provenance "
            "WHERE entity_id=? AND status IN ('tier_a','tier_b') AND adjustment_basis=?",
            (entity_id, ADJUSTED)).fetchall()
    result = []
    for *row, evidence in rows:
        producer = next((ref.get("producer") for ref in json.loads(evidence)
                         if ref.get("kind") == "source" and ref.get("producer")), None)
        if producer is None or producer in producers:
            result.append(tuple(row))
    return result


def _windows(entity_id: str, source_id: str, symbol: str, valid_from: str, valid_to: str) -> list[dict] | None:
    """Audited windows recorded for an interval (None when not recorded)."""
    with storage.get_connection() as conn:
        row = conn.execute(
            "SELECT evidence_json FROM historical_price_provenance WHERE entity_id=? AND source_id=? "
            "AND symbol=? AND valid_from=? AND valid_to=?",
            (entity_id, source_id, symbol, valid_from, valid_to)).fetchone()
    if row is None:
        return None
    refs = [ref for ref in json.loads(row[0]) if ref.get("kind") == "accredited_windows"]
    return refs[0]["windows"] if refs else None


def rankable(windows: list[dict] | None, day: str) -> bool:
    """A ranking on ``day`` may use the interval only if the audit accredited
    the window of the latest audited quarter end on or before ``day`` and
    ``day`` lies within that window's verified holding period. A rejected
    latest window is never bypassed with an older one, and a later
    accreditation is never used."""
    if windows is None:
        return True  # intervals recorded outside the quarterly audit (tests, manual)
    prior = [quarter for quarter in QUARTER_ENDS if quarter <= day]
    if not prior:
        return False
    latest = max(prior)
    return any(window["as_of"] == latest and day <= window["holding_until"] for window in windows)


def has_series(entity_id: str | None, day: str) -> bool:
    if not entity_id:
        return False
    return any(start <= day[:10] < end for _s, _y, start, end, _t in _intervals(entity_id))


def _read(source_id: str, symbol: str, start: str, end: str) -> pd.DataFrame:
    params: tuple[str, ...]
    if source_id == YAHOO_SOURCE:
        query, params = ("SELECT date,close,adj_close FROM prices WHERE symbol=? AND date>=? AND date<? "
                         "ORDER BY date", (symbol, start, end))
    else:
        query, params = ("SELECT date,close,adj_close FROM historical_prices WHERE source_id=? AND symbol=? "
                         "AND date>=? AND date<? ORDER BY date", (source_id, symbol, start, end))
    with storage.get_connection() as conn:
        frame = pd.read_sql_query(query, conn, params=params)
    frame.index = pd.to_datetime(frame.pop("date"))
    return frame[(frame["adj_close"] > 0) & (frame["close"] > 0)]


def _pick(rows: list[tuple], *, covering: tuple[str, str]) -> tuple | None:
    start, end = covering
    candidates = [row for row in rows if row[2] <= start and row[3] > end]
    if not candidates:
        return None
    # Varias fuentes solo solapan si coinciden en retornos; se prefiere Yahoo.
    return sorted(candidates, key=lambda row: (row[0] != YAHOO_SOURCE, row[0]))[0]


def _series_for(entity_id: str, row: tuple) -> pd.DataFrame:
    source_id, symbol, valid_from, valid_to, status = row
    frame = _read(source_id, symbol, valid_from, valid_to)
    frame.attrs.update(entity_id=entity_id, source_id=source_id, source_symbol=symbol,
                       valid_from=valid_from, valid_to=valid_to, price_source_status=status)
    return frame


def ranking_series(entity_id: str | None, as_of: str) -> pd.DataFrame:
    """Serie acreditada que cubre la ventana previa a ``as_of`` (o la historia
    corta acreditada si la acción empezó a cotizar dentro de ella)."""
    if not entity_id:
        return pd.DataFrame()
    day = as_of[:10]
    rows = [row for row in _intervals(entity_id) if rankable(_windows(entity_id, *row[:4]), day)]
    trailing = (date.fromisoformat(day) - timedelta(days=TRAILING_DAYS)).isoformat()
    row = _pick(rows, covering=(trailing, day)) or _pick(rows, covering=(day, day))
    if row is None:
        return pd.DataFrame()
    frame = _series_for(entity_id, row)
    return frame[frame.index <= pd.Timestamp(day)]


def holding_series(entity_id: str | None, day: str) -> pd.DataFrame:
    """Serie acreditada desde ``day`` con el tramo de tenencia más largo."""
    if not entity_id:
        return pd.DataFrame()
    rows = [row for row in _intervals(entity_id) if row[2] <= day[:10] < row[3]]
    if not rows:
        return pd.DataFrame()
    furthest = max(row[3] for row in rows)
    row = sorted([r for r in rows if r[3] == furthest], key=lambda r: (r[0] != YAHOO_SOURCE, r[0]))[0]
    return _series_for(entity_id, row)


def as_traded_close(frame: pd.DataFrame, as_of: str) -> float | None:
    """Cierre negociado en ``as_of``: los archivos ya lo guardan así; la caché
    Yahoo guarda cierres ajustados por splits posteriores (se deshacen)."""
    history = frame[frame.index <= pd.Timestamp(as_of)]
    if history.empty:
        return None
    close = float(history["close"].iloc[-1])
    if frame.attrs.get("source_id") == YAHOO_SOURCE:
        close *= storage.get_split_factor_since(frame.attrs["source_symbol"], as_of)
    return close


def terminal_event(entity_id: str, start: str, end: str) -> dict | None:
    with storage.get_connection() as conn:
        conn.executescript(PROVENANCE_SCHEMA)
        row = conn.execute(
            "SELECT event_date,event_type,status,cash_per_share,exchange_ratio FROM historical_terminal_events "
            "WHERE entity_id=? AND event_date>? AND event_date<=? ORDER BY event_date LIMIT 1",
            (entity_id, start[:10], end[:10])).fetchone()
    if row is None:
        return None
    return dict(zip(("event_date", "event_type", "status", "cash_per_share", "exchange_ratio"), row, strict=True))


def exit_value(frame: pd.DataFrame, entity_id: str, entry: pd.Timestamp, exit_session: pd.Timestamp) -> dict:
    """Valor por unidad de ``adj_close`` al salir de una posición.

    Si la serie llega a ``exit_session`` es el precio negociado. Si termina
    antes: evento terminal confirmado → contraprestación en efectivo pasada a
    la base ajustada (misma fórmula que ``historical_price_policy.terminal_return``);
    si no hay evento confirmado, último precio con ``strict=False``.
    """
    series = frame.loc[frame.index >= entry, ["close", "adj_close"]]
    if exit_session in series.index:
        return {"value": float(series.loc[exit_session, "adj_close"]), "date": exit_session,
                "status": "traded", "strict": True}
    if series.empty:
        return {"value": None, "date": None, "status": "no_prices", "strict": False}
    last_day = series.index[-1]
    last = series.iloc[-1]
    event = terminal_event(entity_id, (entry - pd.Timedelta(days=1)).date().isoformat(),
                           (exit_session + pd.Timedelta(days=10)).date().isoformat())
    if event and event["status"] == "terminal_return_confirmed" and event["event_type"] == "succession" \
            and event.get("exchange_ratio") == 1.0:
        # Canje 1:1 acreditado en el 8-K12B: la posición continúa en el sucesor
        # al mismo valor; se liquida a ese valor y se reinvierte en el rebalanceo.
        return {"value": float(last["adj_close"]), "date": last_day, "status": "succession_one_for_one",
                "strict": True, "event": event}
    if event and event["status"] == "terminal_return_confirmed" and event.get("cash_per_share"):
        return {"value": float(last["adj_close"]) * float(event["cash_per_share"]) / float(last["close"]),
                "date": last_day, "status": "terminal_return_confirmed", "strict": True, "event": event}
    return {"value": float(last["adj_close"]), "date": last_day,
            "status": event["status"] if event else "series_ended_without_event", "strict": False,
            "event": event}
